diff --git a/libheif/image/pixelimage.cc b/libheif/image/pixelimage.cc
index a7c72c2..1c1db62 100644
--- a/libheif/image/pixelimage.cc
+++ b/libheif/image/pixelimage.cc
@@ -1993,6 +1993,16 @@ Error HeifPixelImage::scale_nearest_neighbor(std::shared_ptr<HeifPixelImage>& ou

   // --- scale all channels

+  // Truncating y * in / out biases an odd-length axis toward the previous row.
+  // Round those samples to the nearest source row; an even height already
+  // selects that row with truncation.
+  const auto map_src_y = [this, height](uint32_t y) -> uint32_t {
+    if (m_height & 1) {
+      return static_cast<uint32_t>((static_cast<uint64_t>(y) * m_height + static_cast<uint64_t>(height) / 2) / height);
+    }
+    return static_cast<uint32_t>(static_cast<uint64_t>(y) * m_height / height);
+  };
+
   int nInterleaved = num_interleaved_components_per_plane(m_chroma);
   if (nInterleaved > 1) {
     const auto* comp = find_storage_for_channel(heif_channel_interleaved);
@@ -2020,7 +2030,7 @@ Error HeifPixelImage::scale_nearest_neighbor(std::shared_ptr<HeifPixelImage>& ou
       auto* out_data = out_img->get_channel_memory(heif_channel_interleaved, &out_stride);

       for (uint32_t y = 0; y < out_h; y++) {
-        uint32_t iy = static_cast<uint32_t>(static_cast<uint64_t>(y) * m_height / height);
+        uint32_t iy = map_src_y(y);

         for (uint32_t x = 0; x < out_w; x++) {
           uint32_t ix = static_cast<uint32_t>(static_cast<uint64_t>(x) * m_width / width);
